import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const Senduipath: React.FC = () => {
  //const GAS_URL = "https://script.google.com/macros/s/AKfycbza4KMHau1WZY64yzDuyFAmpz90BoJwGwq1Zah8lMGGUWIKHPELKaPiJ87Yz3QPQJ0/exec"; 
  const GAS_URL = "http://localhost:3000/run-uipath";
  
  const navigate = useNavigate();

  const [loopCount, setLoopCount] = useState(1);
  const [running, setRunning] = useState(false);
  const [result, setResult] = useState("");
  const [toast, setToast] = useState("");

  const showToast = (msg: string) => {
    setToast(msg);
    setTimeout(() => setToast(""), 3000);
  };

  const handleRun = async () => {
    setRunning(true);
    showToast("ジョブ送信中…");
    setResult("");

    try {
      const res = await fetch(GAS_URL, {
        method: "POST",
        mode: "cors",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ loopCount })
      });

      const json = await res.json();
      setResult(JSON.stringify(json, null, 2));
      showToast("ジョブ送信完了");

    } catch (err) {
      setResult("エラー：" + err);
      showToast("ジョブ送信エラー");
    } finally {
      setRunning(false);
    }
  };

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h2>UiPath ジョブ起動</h2>

      <label>
        ループ回数（1〜20）:
        <input
          type="number"
          min="1"
          max="20"
          value={loopCount}
          onChange={(e) => setLoopCount(parseInt(e.target.value, 10))}
          disabled={running}
          style={{ marginLeft: "10px", width: "60px" }}
        />
      </label>

      <br /><br />

      <button onClick={handleRun} disabled={running}>
        {running ? "実行中…" : "ジョブ実行"}
      </button>

      {toast && <div style={{ marginTop: "10px", color: "white", background: "#007bff", padding: "5px 10px", borderRadius: "5px" }}>{toast}</div>}

      <pre style={{ marginTop: "20px", background: "#f0f0f0", padding: "10px" }}>
        {result}
      </pre>
    </div>
  );
};

export default Senduipath;