import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Row, Col, Card } from 'react-bootstrap';

const Home: React.FC = () => {
  const navigate = useNavigate();

  useEffect(() => {
    document.title = 'MainPage';
  }, []);

  // メニューのデータを配列にまとめておくと、管理が楽になります
  const menuItems = [
    { title: '血統組み合わせ表', path: '/table', icon: '🧬', desc: '種牡馬と繁殖牝馬の組み合わせを確認' },
    { title: '配合相手チェック', path: '/blood', icon: '🐴', desc: '最適な配合プランをシミュレーション' },
    { title: 'WBCライバル馬', path: '/wbcrival', icon: '⚔️', desc: 'WBCのライバル馬オッズ' },
    { title: 'レープロ', path: '/schedule', icon: '📅', desc: 'レースプログラムを確認' },
    { title: '勝率計算', path: '/win', icon: '🏆', desc: '単勝・複勝ライドオッズ' },
    { title: 'オッズ判定(簡易版)', path: '/hantei_b', icon: '📊', desc: '初戦オッズでの馬能力を判定' },
  ];

  return (
    <Container className="py-4 py-md-5"> {/* 上下の余白を少し詰めました */}
      <div className="text-center mb-4 mb-md-5">
        <h2 className="fw-bold">なにかのページ</h2>
        <p className="text-muted">おもいついたら随時追加</p>
      </div>

      {/* g-2 (スマホでの隙間を狭く) g-md-4 (PCでは以前のまま) */}
      <Row className="g-2 g-md-4">
        {menuItems.map((item, index) => (
          // xs={6} を追加：スマホで2列にします
          // md={6} lg={3}：タブレットやPCでは以前のサイズを維持します
          <Col xs={6} md={6} lg={3} key={index}>
            <Card 
              className="h-100 shadow-sm text-center border-0"
              style={{ cursor: 'pointer', transition: 'transform 0.2s' }}
              onClick={() => navigate(item.path)}
              // マウスが乗った時に少しフワッと浮き上がるアニメーション
              onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
              onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
            >
              {/* p-3 (スマホでの内側余白を少し詰めました) p-md-4 (PCは以前のまま) */}
              <Card.Body className="p-3 p-md-4">
                {/* アイコンサイズをスマホでは少し小さく (h3) 、PCでは以前のまま (display-4) */}
                <div className="h3 display-md-4 mb-2 mb-md-3">{item.icon}</div>
                <Card.Title className="fw-bold mb-1 mb-md-2" style={{ fontSize: '0.95rem' }}>
                  {item.title}
                </Card.Title>
                <Card.Text className="text-muted small d-none d-md-block">
                  {item.desc}
                </Card.Text>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default Home;