import React, { useState, useEffect } from 'react';
import { RaceData, RaceInterval } from './ScheduleData';
import { useNavigate } from "react-router-dom";
import { Container, Form, Button, Row, Col, Card, Table } from 'react-bootstrap';

const Schedule: React.FC = () => {
    const navigate = useNavigate();
    const [checkFlg, setCheckFlg] = useState<boolean>(false); 
    const [selectedRaceName, setSelectedRaceName] = useState<string>("R1");
    const [selectedInterval, setSelectedInterval] = useState<string>("210");
    const [hour, setHour] = useState('');
    const [minute, setMinute] = useState('');
    const [raceList, setRacelist] = useState(RaceData);
    const [newraceList, setNewRacelist] = useState(RaceData);
    
    // ▼ 追加：主要レースのみ表示するかの判定フラグ ▼
    const [showOnlyMajor, setShowOnlyMajor] = useState<boolean>(false);

    useEffect(() => {
        const now = new Date();
        setHour(now.getHours().toString().padStart(2, '0'));
        setMinute(now.getMinutes().toString().padStart(2, '0'));
    }, []);

    const handleSelectChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedRaceName(event.target.value);
    };
    const handleSelectInterval = (event: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedInterval(event.target.value);
    };

    const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {  
        event.preventDefault();
        setCheckFlg(true);
        const baseDate = new Date();
        baseDate.setHours(parseInt(hour, 10));
        baseDate.setMinutes(parseInt(minute, 10));
        baseDate.setSeconds(0);

        const index = RaceData.findIndex(r => r.raceno === selectedRaceName);
        if (index === -1) return;
        
        const newOrder = [...RaceData.slice(index), ...RaceData.slice(0, index)];

        const interval = parseFloat(selectedInterval);
        const updatedRaces = newOrder.map((race, i) => {
            const raceTime = new Date(baseDate.getTime() + i * interval * 1000);
            const formattedTime = `${raceTime.getHours().toString().padStart(2, '0')}:${raceTime.getMinutes().toString().padStart(2, '0')}`;
            return { ...race, startTime: formattedTime };
        });
        setNewRacelist(updatedRaces);
    }

    const backpage = () => {
        navigate("/");
    };

    // ▼ 追加：表示用リストの生成（スイッチがONなら S, W, WD, MC のみ抽出） ▼
    const displayedRaceList = showOnlyMajor 
        ? newraceList.filter(data => ['S', 'W', 'WD', 'MC'].includes(data.grade))
        : newraceList;

    return (
        <div style={{ backgroundColor: '#f0f2f5', minHeight: '100vh', paddingBottom: '50px' }}>
            <Container className="pt-4" style={{ maxWidth: '600px' }}>
                
                <Card className="shadow border-0 mb-4" style={{ borderRadius: '16px', overflow: 'hidden' }}>
                    <div style={{ height: '6px', backgroundColor: '#3bc0bd' }}></div>
                    <Card.Body className="p-4">
                        <h4 className="text-center mb-4" style={{ color: '#444', fontWeight: '800', letterSpacing: '1px' }}>
                            SCHEDULER <span style={{ color: '#3bc0bd', fontSize: '0.8em' }}>| レープロ想定</span>
                        </h4>
                        
                        <Form onSubmit={handleSubmit}>
                            <div className="mb-4 p-3" style={{ backgroundColor: '#f8f9fa', borderRadius: '12px' }}>
                                <Form.Label className="small fw-bold text-muted mb-2">
                                    <span className="me-2">🕒</span>基準時刻を設定
                                </Form.Label>
                                <div className="d-flex align-items-center justify-content-center gap-2">
                                    <Form.Select 
                                        value={hour} 
                                        onChange={(e) => setHour(e.target.value)} 
                                        className="border-0 shadow-sm"
                                        style={{ borderRadius: '8px', fontWeight: 'bold' }}
                                    >
                                        {Array.from({ length: 24 }, (_, i) => (
                                            <option key={i} value={i.toString().padStart(2, '0')}>{i.toString().padStart(2, '0')}時</option>
                                        ))}
                                    </Form.Select>
                                    <span className="fw-bold text-muted">:</span>
                                    <Form.Select 
                                        value={minute} 
                                        onChange={(e) => setMinute(e.target.value)} 
                                        className="border-0 shadow-sm"
                                        style={{ borderRadius: '8px', fontWeight: 'bold' }}
                                    >
                                        {Array.from({ length: 60 }, (_, i) => (
                                            <option key={i} value={i.toString().padStart(2, '0')}>{i.toString().padStart(2, '0')}分</option>
                                        ))}
                                    </Form.Select>
                                </div>
                            </div>

                            <Row className="mb-3">
                                <Col xs={7}>
                                    <Form.Label className="small fw-bold text-muted mb-2">
                                        <span className="me-2">🏇</span>開始レース
                                    </Form.Label>
                                    <Form.Select 
                                        value={selectedRaceName} 
                                        onChange={handleSelectChange}
                                        className="border-0 shadow-sm"
                                        style={{ borderRadius: '8px', fontSize: '0.9rem' }}
                                    >
                                        {raceList.map((item) => (
                                            <option key={item.raceno} value={item.raceno}>{item.racename}</option>
                                        ))}
                                    </Form.Select>
                                </Col>
                                <Col xs={5}>
                                    <Form.Label className="small fw-bold text-muted mb-2">
                                        <span className="me-2">⏱</span>レース間隔
                                    </Form.Label>
                                    <Form.Select 
                                        value={selectedInterval} 
                                        onChange={handleSelectInterval}
                                        className="border-0 shadow-sm"
                                        style={{ borderRadius: '8px', fontSize: '0.9rem' }}
                                    >
                                        {RaceInterval.map((item) => (
                                            <option key={item.interval} value={item.interval}>{item.value}</option>
                                        ))}
                                    </Form.Select>
                                </Col>
                            </Row>

                            {/* ▼ 追加：絞り込み用スイッチ ▼ */}
                            <div className="mb-4 px-2">
                                <Form.Check 
                                    type="switch"
                                    id="major-race-switch"
                                    label="👑 主要レースのみ表示 (S, W, WD, MC)"
                                    className="fw-bold text-muted small"
                                    checked={showOnlyMajor}
                                    onChange={(e) => setShowOnlyMajor(e.target.checked)}
                                />
                            </div>

                            <Button 
                                type="submit" 
                                className="w-100 border-0 shadow mb-2" 
                                style={{ 
                                    background: 'linear-gradient(45deg, #3bc0bd 0%, #2a9d9b 100%)',
                                    borderRadius: '10px',
                                    padding: '12px',
                                    fontWeight: 'bold',
                                    fontSize: '1.1rem'
                                }}
                            >
                                検索！
                            </Button>
                        </Form>
                    </Card.Body>
                </Card>

                {checkFlg && (
                    <div 
                        className="table-responsive shadow-sm mb-4" 
                        style={{ 
                            borderRadius: '12px', 
                            overflowY: 'auto', 
                            maxHeight: '45vh', 
                            backgroundColor: '#3b3b3b' 
                        }}
                    >
                        <Table className="table-bordered mb-0" style={{ fontSize: "13px", verticalAlign: 'middle' }}>
                            <thead style={{ position: 'sticky', top: 0, zIndex: 1 }}>
                                <tr className="text-center">
                                    <th style={{ backgroundColor: '#3bc0bd', color: '#ffffff', border: 'none', padding: '12px' }}>レース名</th>
                                    <th style={{ backgroundColor: '#3bc0bd', color: '#ffffff', border: 'none', padding: '12px' }}>グレード</th>
                                    <th style={{ backgroundColor: '#3bc0bd', color: '#ffffff', border: 'none', padding: '12px' }}>開始時間</th>
                                </tr>
                            </thead>
                            <tbody>
                                {/* ▼ 修正：newraceList ではなく displayedRaceList を回す ▼ */}
                                {displayedRaceList.map((data, index) => (
                                    <tr key={index} className="text-center">
                                        <td style={{ backgroundColor: '#3b3b3b', color: '#ffffff', borderColor: '#4a4a4a', padding: '10px' }}>
                                            {data.racename}
                                        </td>
                                        <td style={{
                                            backgroundColor:
                                                data.grade === 'G3' ? '#007c0a' : 
                                                data.grade === 'G2' ? '#b51f21' : 
                                                data.grade === 'G1' ? '#163395' :
                                                data.grade === 'S'  ? '#663786' : 
                                                data.grade === 'W'  ? '#cfb736' : 
                                                // ▼ 追加：WDとMCの色設定（一旦仮の色にしています） ▼
                                                data.grade === 'WD' ? '#b8860b' : // 暗めのゴールド
                                                data.grade === 'MC' ? '#800080' : // 紫系
                                                data.grade === 'MS' ? '#d35f00' : '#848484',
                                            color: '#ffffff',
                                            fontWeight: 'bold',
                                            borderColor: '#4a4a4a'
                                        }}>
                                            {data.grade}
                                        </td>
                                        <td style={{ backgroundColor: '#3b3b3b', color: '#ffffff', borderColor: '#4a4a4a', fontWeight: 'bold', fontSize: '1.1em' }}>
                                            {data.startTime}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </Table>
                    </div>
                )}

                <Button 
                    type="reset" 
                    variant="success" 
                    className="w-100 fw-bold shadow-sm" 
                    style={{ padding: '12px', borderRadius: '10px' }}
                    onClick={backpage}
                >
                    戻る
                </Button> 
            </Container>
        </div>
    );
}

export default Schedule;